import test from 'node:test';
import assert from 'node:assert/strict';
import {insightScenario} from './insight-helpers.js';
const headers=token=>({Authorization:'Bearer '+token});
async function token(s,scopes,api=s.api) {return (await api('POST','/tokens',{name:'Final permission proof',scopes})).data.token;}
async function guest(s) {
  await s.api('PATCH','/orgs/'+s.org.id+'/members/'+s.memberUser.id,{role:'guest'});
  await s.api('POST','/projects/'+s.project.id+'/guests',{userId:s.memberUser.id});
}

test('every insight read family checks token scope even with owner role and a valid session cookie',()=>insightScenario(async s=>{
  const auth=headers(await token(s,['self:read','org:read','project:read']));
  const paths=['/search','/search/catalog','/search/suggestions','/filters','/filters/options','/activity','/subscriptions','/notifications','/notification-preferences','/digests','/dashboard','/projects/'+s.project.id+'/dashboard','/insight/options?type=projects'];
  for(const path of paths) {
    const route=path+(path.includes('?')?'&':'?')+'orgId='+s.org.id;
    assert.equal((await s.api('GET',route)).status,200,route+' positive');
    assert.equal((await s.api('GET',route,undefined,auth)).status,403,route+' scope denial');
  }
}));

test('insight read scopes permit reads while denying personal writes and role remains independent of wildcard scope',()=>insightScenario(async s=>{
  const auth=headers(await token(s,['org:read','insight:read']));
  assert.equal((await s.api('GET','/search?orgId='+s.org.id,undefined,auth)).data.total,1);
  const mutations=[['POST','/filters',{orgId:s.org.id,name:'Denied',query:''}],['POST','/subscriptions',{targetType:'issue',targetId:s.issue.id}],['DELETE','/subscriptions/issue/'+s.issue.id],['POST','/notifications/mark',{all:true,read:true}],['PATCH','/notification-preferences',{orgId:s.org.id,emailEnabled:false}],['POST','/digests',{orgId:s.org.id}]];
  for(const [method,path,body] of mutations)assert.equal((await s.api(method,path,body,auth)).status,403,path);
  const memberAuth=headers(await token(s,['*'],s.member));
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;
  assert.equal((await s.member('POST','/orgs/'+s.org.id+'/import',{document,key:'DENY',preview:true},memberAuth)).status,403);
  assert.equal((await s.member('PUT','/projects/'+s.project.id+'/workflow',{statuses:s.project.statuses},memberAuth)).status,403);
  assert.equal((await s.member('PATCH','/issues/'+s.issue.id,{title:'Member positive'},memberAuth)).status,200);
}));

test('guest lookup dashboard search facets and suggestions contain only currently granted project records',()=>insightScenario(async s=>{
  const hidden=(await s.api('POST','/orgs/'+s.org.id+'/projects',{key:'PRIV',name:'Private lookup'})).data.project;
  const secret=(await s.api('POST','/projects/'+hidden.id+'/issues',{title:'Hidden marker',priority:4})).data.issue;
  await s.api('POST','/projects/'+hidden.id+'/labels',{name:'HiddenLabel',color:'#123456'});
  await guest(s);
  const search=(await s.member('GET','/search?orgId='+s.org.id+'&limit=1')).data;
  assert.equal(search.total,1);assert.equal(search.items[0].id,s.issue.id);assert.equal(search.nextCursor,null);
  for(const path of ['/search/catalog','/search/suggestions?q=project:','/filters/options','/dashboard','/insight/options?type=projects']) {
    const result=await s.member('GET',path+(path.includes('?')?'&':'?')+'orgId='+s.org.id);
    assert.equal(result.status,200,path);const body=JSON.stringify(result.data);
    assert(!body.includes(secret.id));assert(!body.includes(hidden.id));assert(!body.includes('HiddenLabel'));assert(!body.includes('PRIV'));
  }
  assert.equal((await s.member('GET','/projects/'+hidden.id+'/export')).status,403);
  await s.api('DELETE','/projects/'+s.project.id+'/guests/'+s.memberUser.id);
  assert.equal((await s.member('GET','/search?orgId='+s.org.id)).data.total,0);
  assert.equal((await s.member('GET','/dashboard?orgId='+s.org.id)).data.totals.issues,0);
}));

test('work candidate and revision paths authorize before choices or conflict snapshots are exposed',()=>insightScenario(async s=>{
  const hidden=(await s.api('POST','/orgs/'+s.org.id+'/projects',{key:'HID',name:'Hidden work'})).data.project;
  const hiddenIssue=(await s.api('POST','/projects/'+hidden.id+'/issues',{title:'Hidden revision'})).data.issue;
  const sprint=(await s.api('POST','/projects/'+hidden.id+'/sprints',{name:'Hidden sprint',startDate:'2026-10-16',endDate:'2026-10-30'})).data.sprint;
  await guest(s);
  for(const path of ['/projects/'+hidden.id+'/issue-options?type=parents','/projects/'+hidden.id+'/assignees','/projects/'+hidden.id+'/workflow','/sprints/'+sprint.id+'/candidates','/sprints/'+sprint.id+'/scope','/sprints/'+sprint.id+'/carry-targets'])assert.equal((await s.member('GET',path)).status,403,path);
  const denied=await s.member('PATCH','/issues/'+hiddenIssue.id,{title:'Denied',expectedRevision:'0'.repeat(64)});
  assert.equal(denied.status,403);assert(!JSON.stringify(denied.data).includes('Hidden revision'));
  const own=await s.member('GET','/projects/'+s.project.id+'/issue-options?type=parents');assert.equal(own.status,200);assert.equal(own.data.items[0].id,s.issue.id);
  const scoped=headers(await token(s,['project:read']));
  assert.equal((await s.api('GET','/projects/'+s.project.id+'/issue-options?type=relations&issueId='+s.issue.id,undefined,scoped)).status,403);
  assert.equal((await s.api('PUT','/projects/'+s.project.id+'/workflow',{statuses:s.project.statuses},scoped)).status,403);
}));

test('private filters and inbox never accept another user identity and team sharing stays inside its organization',()=>insightScenario(async s=>{
  await s.api('PATCH','/issues/'+s.issue.id,{title:'Owner update for member'});
  const notification=(await s.member('GET','/notifications?orgId='+s.org.id)).data.items[0];assert(notification);
  assert.equal((await s.api('PATCH','/notifications/'+notification.id,{read:true})).status,404);
  assert.equal((await s.api('POST','/notifications/mark',{ids:[notification.id],read:true})).status,422);
  assert.equal((await s.api('POST','/subscriptions',{targetType:'issue',targetId:s.issue.id,userId:s.memberUser.id})).status,422);
  const personal=(await s.api('POST','/filters',{orgId:s.org.id,name:'Private',query:''})).data.filter;
  assert.equal((await s.member('GET','/filters/'+personal.id+'/search')).status,404);
  const other=(await s.api('POST','/orgs',{name:'Other team organization'})).data.organization;
  const team=(await s.api('POST','/orgs/'+other.id+'/teams',{name:'Foreign team'})).data.team;
  await s.api('POST','/teams/'+team.id+'/members',{userId:s.user.id});
  assert.equal((await s.api('POST','/filters',{orgId:s.org.id,name:'Foreign share',query:'',visibility:'team',teamId:team.id})).status,422);
  const shared=(await s.api('POST','/filters',{orgId:other.id,name:'Valid share',query:'',visibility:'team',teamId:team.id})).data.filter;
  assert.equal((await s.api('GET','/filters/'+shared.id)).status,200);
  assert.equal((await s.member('GET','/filters/'+shared.id)).status,404);
}));

test('import preview requires every write scope and rejects accessible foreign organization remap targets without writes',()=>insightScenario(async s=>{
  const externalProject=(await s.api('POST','/orgs/'+s.org.id+'/projects',{key:'EXT',name:'External relation'})).data.project;
  const external=(await s.api('POST','/projects/'+externalProject.id+'/issues',{title:'External endpoint'})).data.issue;
  await s.api('POST','/issues/'+s.issue.id+'/relations',{targetIssueId:external.id,kind:'relates'});
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;
  const other=(await s.api('POST','/orgs',{name:'Foreign destination'})).data.organization;
  const foreignProject=(await s.api('POST','/orgs/'+other.id+'/projects',{key:'FOR',name:'Foreign'})).data.project;
  const foreign=(await s.api('POST','/projects/'+foreignProject.id+'/issues',{title:'Foreign target'})).data.issue;
  const input={document,key:'COPY',preview:true,externalIssueMap:{[external.id]:external.id}};
  for(const omitted of ['import:write','project:manage','issue:write','comment:write']) {
    const auth=headers(await token(s,['import:write','project:manage','issue:write','comment:write'].filter(scope=>scope!==omitted)));
    assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',input,auth)).status,403,omitted);
  }
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',input)).status,200);
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{...input,externalIssueMap:{[external.id]:foreign.id}})).status,422);
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{...input,userMap:{[s.memberUser.id]:'foreign-user'}})).status,422);
  assert.equal(s.server.ctx.db.prepare("SELECT count(*) n FROM projects WHERE key='COPY'").get().n,0);
}));
